wrapper_template:
case "${1:-}" in
  issues)
    gh issue list "${@:2}" | head -n "$MAX_LINES"
    ;;
  issue)
    [ -z "${2:-}" ] && { echo "Usage: github.sh issue <number>" >&2; exit 1; }
    gh issue view "$2" | head -n "$MAX_LINES"
    ;;
  issue-create)
    [ -z "${2:-}" ] && { echo "Usage: github.sh issue-create <title> [body]" >&2; exit 1; }
    gh issue create --title "$2" ${3:+--body "$3"}
    ;;
  issue-comment)
    [ -z "${3:-}" ] && { echo "Usage: github.sh issue-comment <number> <body>" >&2; exit 1; }
    gh issue comment "$2" --body "$3"
    ;;
  prs)
    gh pr list "${@:2}" | head -n "$MAX_LINES"
    ;;
  pr)
    [ -z "${2:-}" ] && { echo "Usage: github.sh pr <number>" >&2; exit 1; }
    gh pr view "$2" | head -n "$MAX_LINES"
    ;;
  pr-create)
    [ -z "${2:-}" ] && { echo "Usage: github.sh pr-create <title> <body> <head> <base>" >&2; exit 1; }
    gh pr create --title "$2" --body "${3:-}" --head "${4:-HEAD}" --base "${5:-main}"
    ;;
  pr-diff)
    [ -z "${2:-}" ] && { echo "Usage: github.sh pr-diff <number>" >&2; exit 1; }
    gh pr diff "$2" | head -n "$MAX_LINES"
    ;;
  pr-merge)
    [ -z "${2:-}" ] && { echo "Usage: github.sh pr-merge <number>" >&2; exit 1; }
    gh pr merge "$2" --squash "${@:3}"
    ;;
  search-code)
    [ -z "${2:-}" ] && { echo "Usage: github.sh search-code <query>" >&2; exit 1; }
    gh search code "$2" | head -n "$MAX_LINES"
    ;;
  search-issues)
    [ -z "${2:-}" ] && { echo "Usage: github.sh search-issues <query>" >&2; exit 1; }
    gh search issues "$2" | head -n "$MAX_LINES"
    ;;
  file)
    [ -z "${3:-}" ] && { echo "Usage: github.sh file <owner/repo> <path>" >&2; exit 1; }
    gh api "repos/$2/contents/$3" --jq '.content' | base64 -d | head -n "$MAX_LINES"
    ;;
